        urduTranslation: `حضرت ابو عبیدہ بن الجراح رضی اللہ عنہ فرماتے ہیں: میں نے عرض کیا: یا رسول اللہ! قیامت کے دن سب سے سخت عذاب کسے ملے گا؟ فرمایا: "اس آدمی کو جس نے کسی نبی کو قتل کیا یا جسے کسی نبی نے قتل کیا، اور اس آدمی کو جس نے گمراہی کی پیشوائی کی اور لوگوں کو گمراہ کیا — یہ ان سب کے عذاب کا حصہ پائے گا۔" (مسند احمد: 1/194، حسن)`,
