        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ ﷺ نے فرمایا: "جو شخص کسی مومن کی دنیا کی تکلیفوں میں سے کوئی تکلیف دور کرے، اللہ قیامت کی تکلیفوں میں سے اس کی ایک تکلیف دور فرمائے گا۔ جو تنگدست پر آسانی کرے، اللہ اس پر دنیا و آخرت میں آسانی فرمائے گا۔ جو کسی مسلمان کی پردہ پوشی کرے، اللہ دنیا و آخرت میں اس کی پردہ پوشی فرمائے گا۔ اللہ بندے کی مدد میں رہتا ہے جب تک بندہ اپنے بھائی کی مدد میں رہتا ہے۔" (مسند احمد: 2/252، صحیح)`,
