        arabicText: `عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «مَنْ دَعَا إِلَى هُدًى كَانَ لَهُ مِنَ الأَجْرِ مِثْلُ أُجُورِ مَنْ تَبِعَهُ لَا يَنْقُصُ ذَلِكَ مِنْ أُجُورِهِمْ شَيْئًا، وَمَنْ دَعَا إِلَى ضَلَالَةٍ كَانَ عَلَيْهِ مِنَ الإِثْمِ مِثْلُ آثَامِ مَنْ تَبِعَهُ لَا يَنْقُصُ ذَلِكَ مِنْ آثَامِهِمْ شَيْئًا». (مسند أحمد: 2/397، صحيح — رواه مسلم)`,
        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "جس نے ہدایت کی طرف دعوت دی اسے اپنے پیروکاروں جیسا اجر ملے گا، اس سے ان کے اجر میں کوئی کمی نہیں آئے گی۔ اور جس نے گمراہی کی طرف بلایا اس پر اپنے پیروکاروں جیسا گناہ ہوگا، اس سے ان کے گناہ میں کوئی کمی نہیں آئے گی۔" (مسند احمد: 2/397، صحیح)`,
