        urduTranslation: `حضرت عبد اللہ بن مسعود رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "سچ کو لازم پکڑو، کیونکہ سچ نیکی کی راہ دکھاتا ہے اور نیکی جنت کی راہ دکھاتی ہے۔ آدمی سچ بولتا رہتا ہے اور سچائی کی تلاش میں رہتا ہے حتیٰ کہ اللہ کے یہاں اسے صدیق لکھ دیا جاتا ہے۔ اور جھوٹ سے بچو، کیونکہ جھوٹ فسق و فجور کی راہ دکھاتا ہے اور فجور جہنم کی راہ دکھاتا ہے۔ آدمی جھوٹ بولتا رہتا ہے اور جھوٹ ڈھونڈتا رہتا ہے حتیٰ کہ اللہ کے یہاں اسے کذاب لکھ دیا جاتا ہے۔" (مسند احمد: 1/384، متفق علیہ)`,
