        urduTranslation: `حضرت عقبہ بن عامر رضی اللہ عنہ فرماتے ہیں: میں نے عرض کیا: یا رسول اللہ! نجات کس چیز میں ہے؟ آپ ﷺ نے فرمایا: "اپنی زبان قابو میں رکھو، گھر تمہارے لیے کافی ہو، اور اپنے گناہوں پر روتے رہو۔" (مسند احمد: 4/148، حسن)`,
