        arabicText: `عَنْ حُذَيْفَةَ بْنِ اليَمَانِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ ﷺ يَقُولُ: «لَا يَدْخُلُ الجَنَّةَ قَتَّاتٌ». (مسند أحمد: 5/382، متفق علیه)`,
        urduTranslation: `حضرت حذیفہ بن الیمان رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: "چغل خور (لوگوں کی چھپی باتیں اڑا کر فساد پیدا کرنے والا) جنت میں داخل نہیں ہوگا۔" (مسند احمد: 5/382، متفق علیہ)`,
        tashreeh: `قتات اور نمام اس شخص کو کہتے ہیں جو ایک کی بات دوسرے تک فساد اور لڑائی ڈالنے کی نیت سے پہنچائے۔ یہ گناہِ کبیرہ ہے جس سے معاشرتی امن تباہ ہوتا ہے۔ اس سخت وعید سے مقصود امت کو زبانی فتنوں اور غیبت و چغلی سے باز رکھنا ہے۔`,
