        urduTranslation: `حضرت ابو مسعود عقبہ بن عمرو انصاری رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: "پچھلی تمام نبوتوں کے کلام سے جو بات لوگوں تک متفقہ طور پر پہنچی ہے وہ یہ ہے: جب تم حیا نہ کرو تو پھر جو چاہو کرو۔" (مسند احمد: 4/121، صحیح)`,
        tashreeh: `حیا تمام شریعتوں اور تمام انبیاء علیہم السلام کا متفقہ اخلاق رہا ہے۔ اس حدیث کا معنیٰ بطورِ وعید اور تہدید ہے یعنی جب انسان سے حیا چھن جائے تو وہ ہر برائی اور بے ہودگی پر دلیر ہو جاتا ہے اور اسے روکنے والی کوئی طاقت باقی نہیں رہتی۔`,
