        urduTranslation: `حضرت اسماء بنت ابی بکر صدیق رضی اللہ عنہما فرماتی ہیں کہ مجھ سے رسول اللہ ﷺ نے ارشاد فرمایا: "تم اللہ کی راہ میں خرچ کرو، اور گن گن کر مت رکھو ورنہ اللہ بھی تمہیں گن گن کر دے گا، اور تھیلی کا منہ بند کر کے مت رکھو ورنہ اللہ بھی اپنی رحمت کا دروازہ بند فرما دے گا، جتنا بھی تم سے ہو سکے ضرور کچھ نہ کچھ راہِ خدا میں دیتی رہو۔" (مسند احمد: 6/345، متفق علیہ)`,
        tashreeh: `یہ حدیث فیاضی اور سخاوت کی ترغیب دیتی ہے۔ مال کو جمع کر کے اس پر سانپ بن کر بیٹھ جانا اور گن گن کر رکھنا اللہ کی برکتوں اور رزق کی وسعت کو روک دیتا ہے۔ جس قدر انسان کشادہ دلی سے راہِ خدا میں دیتا ہے اسی قدر اللہ تعالیٰ اس کے رزق میں برکتیں عطا فرماتا ہے۔`,
