        urduTranslation: `حضرت ام عطیہ انصاریہ رضی اللہ عنہا فرماتی ہیں کہ جب رسول اللہ ﷺ کی صاحبزادی (حضرت زینبؓ) کا انتقال ہوا تو آپ ہمارے پاس تشریف لائے اور فرمایا: "اسے تین بار، یا پانچ بار، یا اگر مناسب سمجھو تو اس سے زیادہ بار پانی اور بیری کے پتوں سے غسل دو، اور آخری بار کے غسل میں کافور (یا فرمایا کافور کا کچھ حصہ) ڈال دو، اور جب تم فارغ ہو جاؤ تو مجھے خبر دینا۔" پس جب ہم فارغ ہوئیں تو ہم نے آپ کو اطلاع دی۔ آپ ﷺ نے ہمیں اپنا تہبند مبارک عنایت فرمایا اور ارشاد فرمایا: "اس کو اس کے جسم کے ساتھ سب سے اندر کفن کے طور پر لپیٹ دو۔" (مسند احمد: 6/408، متفق علیہ)`,
