        arabicText: `عَنْ جُوَيْرِيَةَ رَضِيَ اللَّهُ عَنْهَا، أَنَّ النَّبِيَّ ﷺ خَرَجَ مِنْ عِنْدِهَا بُكْرَةً حِينَ صَلَّى الصُّبْحَ وَهِيَ فِي مَسْجِدِهَا، ثُمَّ رَجَعَ بَعْدَ أَنْ أَضْحَى وَهِيَ جَالِسَةٌ، فَقَالَ: «مَا زِلْتِ عَلَى الحَالِ الَّتِي فَارَقْتُكِ عَلَيْهَا؟» قَالَتْ: نَعَمْ، قَالَ: «لَقَدْ قُلْتُ بَعْدَكِ أَرْبَعَ كَلِمَاتٍ، ثَلَاثَ مَرَّاتٍ، لَوْ وُزِنَتْ بِمَا قُلْتِ مُنْذُ اليَوْمِ لَوَزَنَتْهُنَّ: سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ». (مسند أحمد: 6/325، صحيح — رواه مسلم)`,
        urduTranslation: `ام المؤمنین حضرت جویریہ رضی اللہ عنہا سے روایت ہے کہ نبی اکرم ﷺ صبح کے وقت نمازِ فجر پڑھ کر ان کے پاس سے تشریف لے گئے جبکہ وہ اپنی جائے نماز پر بیٹھی ذکر کر رہی تھیں، پھر آپ چاشت کے وقت واپس آئے تو وہ بدستور اسی حالت میں بیٹھی تھیں۔ آپ ﷺ نے فرمایا: "کیا تم اسی حالت پر ہو جس پر میں تمہیں چھوڑ کر گیا تھا؟" انہوں نے عرض کیا: جی ہاں۔ آپ ﷺ نے فرمایا: "میں نے تمہارے بعد چار ایسے کلمات تین بار کہے ہیں کہ اگر ان کا وزن تمہارے آج کے سارے وظیفے سے کیا جائے تو وہ ان پر بھاری ہو جائیں گے: 'سُبْحَانَ اللَّهِ وَبِحَمْدِهِ، عَدَدَ خَلْقِهِ، وَرِضَا نَفْسِهِ، وَزِنَةَ عَرْشِهِ، وَمِدَادَ كَلِمَاتِهِ' (اللہ پاک ہے اپنی حمد کے ساتھ، اس کی مخلوق کی تعداد کے برابر، اس کی ذات کی رضا کے مطابق، اس کے عرش کے وزن جتنا، اور اس کے کلمات کی سیاہی کے پھیلاؤ کے برابر)۔" (مسند احمد: 6/325، صحیح)`,
