        id: 'musnad_ahmad_63_01',
        arabicText: `عَنْ مَيْمُونَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: وَضَعْتُ لِرَسُولِ اللَّهِ ﷺ غُسْلًا، فَسَتَرْتُهُ، فَصَبَّ عَلَى يَدَيْهِ فَغَسَلَهُمَا مَرَّتَيْنِ أَوْ ثَلَاثًا، ثُمَّ أَفْرَغَ بِيَمِينِهِ عَلَى شِمَالِهِ فَغَسَلَ فَرْجَهُ، ثُمَّ دَلَكَ يَدَهُ بِالأَرْضِ، ثُمَّ مَضْمَضَ وَاسْتَنْشَقَ وَغَسَلَ وَجْهَهُ وَيَدَيْهِ، ثُمَّ صَبَّ عَلَى رَأْسِهِ ثَلَاثًا، وَأَفَاضَ عَلَى سَائِرِ جَسَدِهِ، ثُمَّ تَنَحَّى فَغَسَلَ رِجْلَيْهِ، فَأَتَيْتُهُ بِالمِنْدِيلِ فَرَدَّهَا وَجَعَلَ يَنْفُضُ المَاءَ بِيَدِهِ. (مسند أحمد: 6/330، متفق علیه)`,
        urduTranslation: `ام المؤمنین حضرت میمونہ رضی اللہ عنہا فرماتی ہیں: "میں نے رسول اللہ ﷺ کے لیے غسل کا پانی رکھا اور آپ پر پردہ کیا، آپ نے پہلے اپنے دونوں ہاتھوں پر پانی ڈال کر انہیں دو یا تین بار دھویا، پھر دائیں ہاتھ سے بائیں ہاتھ پر پانی انڈیلا اور اپنی شرمگاہ کو دھویا، پھر اپنے ہاتھ کو زمین پر مل کر صاف کیا، پھر کلی کی اور ناک میں پانی ڈالا اور چہرہ اور بازو دھوئے (جیسا کہ نماز کا وضو ہوتا ہے)، پھر اپنے سر پر تین بار پانی بہایا اور پورے جسم پر پانی بہا دیا، پھر اس جگہ سے ہٹ کر الگ ہو کر اپنے دونوں پاؤں دھوئے۔ میں نے آپ کو تولیہ پیش کیا تو آپ نے اسے واپس کر دیا اور اپنے دستِ مبارک سے پانی جھاڑنے لگے۔" (مسند احمد: 6/330، متفق علیہ)`,
        tashreeh: `یہ حدیث مسنون غسلِ جنابت کے تمام ارکان و آداب کی بنیادی فقہی دلیل ہے۔ غسل سے پہلے وضو کرنا، پردے کا اہتمام کرنا، طہارت کے بعد جگہ بدل کر پاؤں دھونا، اور تولیے کے بجائے ہاتھوں سے پانی جھاڑنا مسنون آداب میں سے ہے۔`,
