        urduTranslation: `سیدہ فاطمۃ الزہراء رضی اللہ عنہا سے روایت ہے کہ نبی اکرم ﷺ نے ان سے فرمایا: "تمہیں اس وصیت پر عمل کرنے سے کون سی چیز روکتی ہے جو میں تمہیں کرتا ہوں؟ کہ جب تم صبح کرو اور جب تم شام کرو تو یہ دعا پڑھا کرو: 'اے ہمیشہ زندہ رہنے والے! اے کائنات کو سنبھالنے والے! میں تیری ہی رحمت کے ذریعے مدد طلب کرتا ہوں، میرے تمام حالات اور معاملات کو درست اور سنوار دے، اور مجھے پلک جھپکنے کے برابر بھی میرے نفس کے حوالے نہ فرما'۔" (مسند احمد: 3/40، حسن)`,
