        urduTranslation: `حضرت ابو امامہ باہلی رضی اللہ عنہ فرماتے ہیں کہ میں نے حجۃ الوداع کے موقع پر رسول اللہ ﷺ کو خطبہ دیتے ہوئے سنا، آپ نے فرمایا: "اپنے رب اللہ کا تقویٰ اختیار کرو، اپنی پانچ وقت کی نمازیں پڑھو، اپنے رمضان کے مہینے کے روزے رکھو، اپنے مالوں کی زکوٰۃ خوش دلی سے ادا کرو، اور اپنے حکمرانوں کی (معروف میں) اطاعت کرو، تم اپنے رب کی جنت میں داخل ہو جاؤ گے۔" (مسند احمد: 5/251، صحیح)`,
