        urduTranslation: `حضرت ابو برزہ اسلمی رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: "قیامت کے دن کسی بندے کے دونوں قدم (میزان و حساب کی جگہ سے) اس وقت تک نہیں ہٹ سکتے جب تک کہ اس سے چار باتوں کا سوال نہ کر لیا جائے: (1) اس کی عمر کے بارے میں کہ اسے کس کام میں فنا کیا؟ (2) اس کے علم کے بارے میں کہ اس پر کتنا عمل کیا؟ (3) اس کے مال کے بارے میں کہ کہاں سے کمایا اور کہاں خرچ کیا؟ (4) اور اس کے جسم کے بارے میں کہ اسے کس چیز میں گھلایا اور پرانا کیا؟" (مسند احمد: 4/414، صحیح)`,
