        id: 'musnad_ahmad_70_01',
        arabicText: `عَنْ سَلَمَةَ بْنِ الأَكْوَعِ رَضِيَ اللَّهُ عَنْهُ قَالَ: غَزَوْنَا مَعَ رَسُولِ اللَّهِ ﷺ حُنَيْنًا، فَلَمَّا التَقَى النَّاسُ وَلَّى بَعْضُهُمْ، وَرَسُولُ اللَّهِ ﷺ ثَابِتٌ عَلَى بَغْلَتِهِ الشَّهْبَاءِ، فَنَزَلَ عَنْهَا وَأَخَذَ قَبْضَةً مِنْ تُرَابٍ فَرَمَى بِهَا فِي وُجُوهِ القَوْمِ وَقَالَ: «شَاهَتِ الوُجُوهُ»، فَمَا خَلَقَ اللَّهُ مِنْهُمْ إِنْسَانًا إِلَّا مَلَأَ عَيْنَيْهِ تُرَابًا بِتِلْكَ القَبْضَةِ، فَانْهَزَمُوا. (مسند أحمد: 4/51، متفق علیه)`,
        urduTranslation: `حضرت سلمہ بن الاکوع رضی اللہ عنہ فرماتے ہیں: "ہم نے رسول اللہ ﷺ کے ہمراہ غزوۂ حنین میں جہاد کیا۔ جب لشکر آمنے سامنے ہوئے تو (اچانک تیر اندازی کی وجہ سے) مسلمانوں کا ایک حصہ پیچھے ہٹ گیا، مگر رسول اللہ ﷺ اپنی سفید خچر پر پہاڑ کی طرح ثابت قدم رہے! پھر آپ نیچے تشریف لائے اور زمین سے ایک مٹھی خاک لے کر دشمنوں کے چہروں کی طرف پھینکی اور فرمایا: 'چہرے بگڑ جائیں!' پس اللہ نے ان میں سے کوئی ایسا کافر پیدا نہیں کیا تھا جس کی دونوں آنکھیں اس ایک مٹھی مٹی سے نہ بھر گئی ہوں، اور وہ سب شکست کھا کر بھاگ نکلے۔" (مسند احمد: 4/51، متفق علیہ)`,
