        urduTranslation: `حضرت طارق بن شہاب رضی اللہ عنہ سے مروی ہے کہ نبی اکرم ﷺ نے ارشاد فرمایا: "نمازِ جمعہ باجماعت ادا کرنا ہر مسلمان پر حق اور فرض ہے سوائے چار افراد کے: (1) غلام جو کسی کی ملکیت میں ہو، (2) عورت، (3) نابالغ بچہ، (4) یا ایسا مریض (جو مسجد جانے سے معذور ہو)۔" (مسند احمد: 4/311، صحیح)`,
