        arabicText: `عَنْ وَابِصَةَ بْنِ مَعْبَدٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: أَتَيْتُ رَسُولَ اللَّهِ ﷺ فَقَالَ: «جِئْتَ تَسْأَلُ عَنِ البِرِّ وَالإِثْمِ؟» قُلْتُ: نَعَمْ، فَجَمَعَ أَصَابِعَهُ فَضَرَبَ بِهَا صَدْرِي وَقَالَ: «اسْتَفْتِ نَفْسَكَ، اسْتَفْتِ قَلْبَكَ يَا وَابِصَةُ - ثَلَاثًا -، البِرُّ مَا اطْمَأَنَّتْ إِلَيْهِ النَّفْسُ وَاطْمَأَنَّ إِلَيْهِ القَلْبُ، وَالإِثْمُ مَا حَاكَ فِي النَّفْسِ وَتَرَدَّدَ فِي الصَّدْرِ، وَإِنْ أَفْتَاكَ النَّاسُ وَأَفْتَوْكَ». (مسند أحمد: 4/227، حديث حسن)`,
        urduTranslation: `حضرت وابصہ بن معبد اسدی رضی اللہ عنہ فرماتے ہیں کہ میں رسول اللہ ﷺ کی خدمت میں حاضر ہوا، تو آپ نے میرے پوچھنے سے پہلے ہی فرمایا: "کیا تم نیکی اور گناہ کے بارے میں پوچھنے آئے ہو؟" میں نے عرض کیا: جی ہاں یا رسول اللہ! آپ ﷺ نے اپنی مبارک انگلیاں جمع فرما کر میرے سینے پر ماریں اور ارشاد فرمایا: "اپنے نفس سے فتویٰ لو، اپنے دل سے فتویٰ لو اے وابصہ! (تین بار فرمایا)۔ نیکی وہ ہے جس پر نفس مطمئن ہو جائے اور دل کو قرار آ جائے، اور گناہ وہ ہے جو تمہارے نفس میں کھٹکے اور سینے میں تردد پیدا کرے، اگرچہ لوگ تمہیں (اس کے جواز کا) فتویٰ دیتے رہیں اور دیتے رہیں!" (مسند احمد: 4/227، حسن)`,
