        urduTranslation: `حضرت معقل بن یسار رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: "کوئی بھی حکمران یا ذمہ دار جسے مسلمانوں کی رعیت اور عوام کا نگران بنایا جائے، پھر وہ اس حال میں مرے کہ اس نے ان کے ساتھ خیانت اور دھوکہ کیا ہو، تو اللہ تعالیٰ اس پر جنت کو قطعی حرام فرما دیتا ہے!" (مسند احمد: 5/25، متفق علیہ)`,
