        id: 'musnad_ahmad_81_01',
        arabicText: `عَنْ عَبْدِ اللَّهِ بْنِ مُغَفَّلٍ رَضِيَ اللَّهُ عَنْهُ، أَنَّهُ رَأَى رَجُلًا يَخْذِفُ فَقَالَ لَهُ: لَا تَخْذِفْ، فَإِنَّ رَسُولَ اللَّهِ ﷺ نَهَى عَنِ الخَذْفِ، وَقَالَ: «إِنَّهُ لَا يُصَادُ بِهِ صَيْدٌ، وَلَا يُنْكَأُ بِهِ عَدُوٌّ، وَلَكِنَّهُ يَكْسِرُ السِّنَّ، وَيَفْقَأُ العَيْنَ». (مسند أحمد: 4/86، متفق علیه)`,
        urduTranslation: `حضرت عبد اللہ بن مغفل رضی اللہ عنہ سے روایت ہے کہ انہوں نے ایک شخص کو کنکریاں پھینکتے (خنکیاں چلاتے) دیکھا تو اس سے فرمایا: کنکریاں مت پھینکو، کیونکہ رسول اللہ ﷺ نے کنکری پھینکنے سے منع فرمایا ہے اور ارشاد فرمایا: "اس سے نہ تو کوئی شکار کیا جا سکتا ہے اور نہ دشمن کو کوئی گزند پہنچائی جا سکتی ہے، البتہ یہ کسی کا دانت توڑ دیتی ہے یا آنکھ پھوڑ دیتی ہے۔" (مسند احمد: 4/86، متفق علیہ)`,
