        arabicText: `عَنْ عَبْدِ اللَّهِ بْنِ أَبِي أَوْفَى رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ فِي بَعْضِ أَيَّامِهِ الَّتِي لَقِيَ فِيهَا العَدُوَّ: «يَا أَيُّهَا النَّاسُ، لَا تَتَمَنَّوْا لِقَاءَ العَدُوِّ، وَاسْأَلُوا اللَّهَ العَافِيَةَ، فَإِذَا لَقِيتُمُوهُمْ فَاصْبِرُوا، وَاعْلَمُوا أَنَّ الجَنَّةَ تَحْتَ ظِلَالِ السُّيُوفِ». (مسند أحمد: 4/353، متفق علیه)`,
        urduTranslation: `حضرت عبد اللہ بن ابی اوفی رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے دشمن کے مقابلے کے ایک دن لوگوں سے خطاب فرمایا: "اے لوگو! دشمن سے مڈبھیڑ اور جنگ کی تمنا مت کرو، بلکہ اللہ تعالیٰ سے عافیت اور سلامتی مانگو۔ لیکن جب تمہارا دشمن سے آمنا سامنا ہو ہی جائے تو پھر چٹان کی طرح ڈٹ جاؤ اور صبر کرو، اور خوب جان لو کہ جنت تلواروں کے سائے تلے ہے!" (مسند احمد: 4/353، متفق علیہ)`,
        tashreeh: `اسلام خون ریزی یا جنگ پسندی کی تمنا کرنے کی اجازت نہیں دیتا؛ بندۂ مؤمن ہمیشہ عافیت کا طلبگار رہتا ہے۔ لیکن اگر حق و باطل کا معرکہ پیش آ جائے تو پیٹھ پھیرنا حرام ہے، بلکہ بہادری اور ثبات کے ساتھ جان کی بازی لگا دینا ہی جنت کی چابی ہے۔`,
