        urduTranslation: `حضرت عبد اللہ بن زبیر رضی اللہ عنہما فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: "میری اس مسجد (مسجدِ نبوی) میں ایک نماز پڑھنا مسجدِ حرام کے علاوہ باقی تمام مساجد کی ایک ہزار نمازوں سے افضل ہے، اور مسجدِ حرام میں ایک نماز پڑھنا میری اس مسجد کی ایک لاکھ نمازوں سے افضل ہے!" (مسند احمد: 4/5، صحیح)`,
