        arabicText: `عَنْ قَيْسِ بْنِ سَعْدِ بْنِ عُبَادَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّ أَبَاهُ دَفَعَهُ إِلَى النَّبِيِّ ﷺ يَخْدُمُهُ، قَالَ: فَمَرَّ بِيَ النَّبِيُّ ﷺ وَقَدْ صَلَّيْتُ فَضَرَبَنِي بِرِجْلِهِ وَقَالَ: «أَلَا أَدُلُّكَ عَلَى بَابٍ مِنْ أَبْوَابِ الجَنَّةِ؟» قُلْتُ: بَلَى، قَالَ: «لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ». (مسند أحمد: 5/422، حديث صحيح)`,
        urduTranslation: `حضرت قیس بن سعد بن عبادہ رضی اللہ عنہ سے روایت ہے کہ ان کے والد نے انہیں رسول اللہ ﷺ کی خدمت کے لیے پیش کیا۔ وہ فرماتے ہیں کہ میں نماز پڑھ کر بیٹھا تھا کہ نبی اکرم ﷺ میرے پاس سے گزرے، آپ نے اپنے پاؤں مبارک سے مجھے ہلکا سا چھوا اور فرمایا: "کیا میں تمہیں جنت کے دروازوں میں سے ایک دروازہ نہ بتاؤں؟" میں نے عرض کیا: ضرور یا رسول اللہ! آپ ﷺ نے فرمایا: " 'لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ' (گناہوں سے پھرنے اور نیکی کرنے کی کوئی طاقت نہیں مگر اللہ ہی کی توفیق سے)۔" (مسند احمد: 5/422، صحیح)`,
