        urduTranslation: `حضرت ام الفضل بنت الحارث رضی اللہ عنہا سے مروی ہے کہ عرفہ کے دن لوگوں نے ان کے پاس رسول اللہ ﷺ کے روزے کے بارے میں بحث کی؛ بعض نے کہا آپ روزے سے ہیں اور بعض نے کہا آپ روزے سے نہیں ہیں۔ پس ام الفضل نے آپ کی خدمت میں دودھ کا ایک پیالہ بھیجا جبکہ آپ اونٹ پر سوار وقوف فرما رہے تھے، پس آپ ﷺ نے وہ دودھ پی لیا (اور سب کو معلوم ہو گیا کہ حاجی کے لیے عرفہ کے دن روزہ نہ رکھنا افضل ہے)۔ (مسند احمد: 6/339، متفق علیہ)`,
