        urduTranslation: `حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ نبی اکرم ﷺ نے ارشاد فرمایا: "تین خصلتیں ایسی ہیں کہ جس شخص میں وہ موجود ہوں وہ ایمان کی مٹھاس پا لیتا ہے: (1) یہ کہ اللہ اور اس کا رسول اس کے نزدیک باقی تمام کائنات سے زیادہ محبوب ہو جائیں، (2) یہ کہ وہ کسی انسان سے صرف اور صرف اللہ کی رضا کے لیے محبت رکھے، (3) اور یہ کہ وہ کفر میں واپس لوٹنے کو ایسا برا سمجھے جیسا کہ آگ میں پھینکے جانے کو برا سمجھتا ہے!" (مسند احمد: 3/103، متفق علیہ)`,
