        urduTranslation: `حضرت ابو موسیٰ اشعری رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے ارشاد فرمایا: "اچھے ہم نشین اور برے ہم نشین کی مثال مشک بیچنے والے (عطار) اور بھٹی دھونکنے والے (لوہار) جیسی ہے۔ کستوری بیچنے والا یا تو تمہیں مفت خوشبو تحفہ دے گا، یا تم اس سے خرید لو گے، یا کم از کم تمہیں اس کی دکان سے اچھی خوشبو آئے گی۔ اور لوہار کی بھٹی یا تو تمہارے کپڑے جلا دے گی، یا تمہیں اس سے ناگوار بدبو اور دھواں پہنچے گا!" (مسند احمد: 4/408، متفق علیہ)`,
