        urduTranslation: `حضرت ابو ذر غفاری رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: "اپنے مسلمان بھائی کے سامنے تمہارا مسکرا کر دیکھنا تمہارے لیے صدقہ ہے، تمہارا نیکی کا حکم دینا اور برائی سے روکنا صدقہ ہے، راستہ بھولے ہوئے شخص کو راستہ دکھانا صدقہ ہے، کمزور نظر والے کو راستہ دکھا کر مدد کرنا صدقہ ہے، راستے سے پتھر، کانٹا اور ہڈی ہٹانا صدقہ ہے، اور اپنے ڈول سے اپنے بھائی کے ڈول میں پانی انڈیل دینا تمہارے لیے صدقہ ہے!" (مسند احمد: 5/168، حسن)`,
