        urduTranslation: `حضرت ابو ایوب انصاری رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: "کسی مسلمان کے لیے یہ جائز اور حلال نہیں کہ وہ اپنے مسلمان بھائی سے تین راتوں سے زیادہ بول چال اور تعلقات بند رکھے کہ جب دونوں کا آمنا سامنا ہو تو یہ ادھر منہ پھیر لے اور وہ ادھر منہ پھیر لے، اور ان دونوں میں سے بہترین اور افضل وہ ہے جو سلام کرنے میں پہل کرے!" (مسند احمد: 5/416، متفق علیہ)`,
