        id: 'musnad_ahmad_119_01',
        arabicText: `عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: «أَلَا أُخْبِرُكُمْ بِالفَقِيهِ حَقَّ الفَقِيهِ؟ الَّذِي لَا يُقَنِّطُ النَّاسَ مِنْ رَحْمَةِ اللَّهِ، وَلَا يُرَخِّصُ لَهُمْ فِي مَعَاصِي اللَّهِ، وَلَا يُؤَمِّنُهُمْ مِنْ مَكْرِ اللَّهِ، وَلَا يَدَعُ القُرْآنَ رَغْبَةً عَنْهُ إِلَى غَيْرِهِ، إِنَّهُ لَا خَيْرَ فِي عِبَادَةٍ لَا عِلْمَ فِيهَا، وَلَا عِلْمٍ لَا فَهْمَ فِيهِ، وَلَا قِرَاءَةٍ لَا تَدَبُّرَ فِيهَا». (مسند أحمد: فضائل الصحابة: 1/450، إسناده حسن)`,
        urduTranslation: `امیر المؤمنین حضرت علی المرتضیٰ رضی اللہ عنہ نے ارشاد فرمایا: "کیا میں تمہیں نہ بتاؤں کہ کامل فقیہ اور حقیقی عالم کون ہے؟ وہ ہے جو لوگوں کو اللہ کی رحمت سے ناامید نہ کرے، اور نہ ہی انہیں اللہ کی نافرمانیوں اور گناہوں کی کھلی چھوٹ دے، اور نہ ہی انہیں اللہ کی پکڑ اور عذاب سے بے خوف کرے، اور نہ ہی قرآن کو چھوڑ کر کسی اور چیز کی طرف راغب ہو جائے۔ بے شک اس عبادت میں کوئی بھلائی نہیں جس میں علم نہ ہو، اور اس علم میں کوئی خیر نہیں جس میں فہم و بصیرت نہ ہو، اور اس تلاوت میں کوئی برکت نہیں جس میں تدبر و غور و فکر نہ ہو!" (مسند احمد: فضائل الصحابہ: 1/450، حسن)`,
        tashreeh: `باب العلم حضرت علی المرتضیٰ کا یہ قولِ فیصل فقہ اور دعوت کی اصل روح کو واضح کرتا ہے۔ عالم وہ نہیں جو صرف فتوے دے بلکہ وہ ہے جو خوف اور رجاء میں توازن قائم رکھے اور قرآنی تدبر کے ساتھ امت کی رہنمائی کرے۔`,
