        arabicText: `عَنْ أَبِي ثَعْلَبَةَ الخُشَنِيِّ رَضِيَ اللَّهُ عَنْهُ، عَنِ النَّبِيِّ ﷺ قَالَ: «إِنَّ أَحَبَّكُمْ إِلَيَّ وَأَقْرَبَكُمْ مِنِّي مَجْلِسًا يَوْمَ القِيَامَةِ: أَحَاسِنُكُمْ أَخْلَاقًا، وَإِنَّ أَبْغَضَكُمْ إِلَيَّ وَأَبْعَدَكُمْ مِنِّي مَجْلِسًا يَوْمَ القِيَامَةِ: الثَّرْثَارُونَ، وَالمُتَشَدِّقُونَ، وَالمُتَفَيْهِقُونَ». (مسند أحمد: 4/193، حديث حسن)`,
        urduTranslation: `حضرت ابو ثعلبہ خشنی رضی اللہ عنہ سے روایت ہے کہ نبی اکرم ﷺ نے ارشاد فرمایا: "قیامت کے دن تم میں سے میرے سب سے زیادہ محبوب اور مجلس میں مجھ سے سب سے زیادہ قریب وہ لوگ ہوں گے جن کے اخلاق سب سے اچھے ہوں گے، اور قیامت کے دن تم میں سے میرے نزدیک سب سے زیادہ ناپسندیدہ اور مجھ سے سب سے زیادہ دور وہ لوگ ہوں گے جو فضول گو (بکواسی)، تکبر سے منہ پھلا کر بولنے والے، اور خود نمائی کرنے والے ہوں گے!" (مسند احمد: 4/193، حسن)`,
