        urduTranslation: `حضرت شداد بن اوس رضی اللہ عنہ فرماتے ہیں کہ میں نے رسول اللہ ﷺ سے دو باتیں یاد رکھی ہیں، آپ نے فرمایا: "اللہ تعالیٰ نے ہر چیز میں احسان اور حسنِ سلوک کو فرض کیا ہے؛ پس جب تم (کسی شرعی مجرم کو) قتل کرو تو اچھے طریقے سے قتل کرو، اور جب تم کسی جانور کو ذبح کرو تو اچھے اور رحم دلانہ طریقے سے ذبح کرو، اور تم میں سے ہر شخص کو چاہیے کہ وہ اپنی چھری کو خوب تیز کر لے اور اپنے ذبیحہ کو راحت پہنچائے (تکلیف نہ دے)!" (مسند احمد: 4/123، صحیح)`,
