        urduTranslation: `حضرت عمران بن حصین رضی اللہ عنہ فرماتے ہیں کہ میں نبی اکرم ﷺ کی خدمت میں حاضر ہوا تو اہل یمن نے عرض کیا: ہم آپ کے پاس اس لیے آئے ہیں کہ ہم آپ سے کائنات کے آغاز اور پہلی پیدائش کے بارے میں پوچھیں؟ آپ ﷺ نے فرمایا: "سب سے پہلے صرف اللہ تعالیٰ تھا اور اس سے پہلے کوئی بھی چیز موجود نہیں تھی، اور اس کا عرش پانی پر تھا، اور اس نے لوحِ محفوظ میں ہر ہر چیز کی تقدیر لکھ دی، اور آسمانوں اور زمین کو پیدا فرمایا!" (مسند احمد: 4/431، صحیح)`,
