        urduTranslation: `حضرت ابو برزہ اسلمی رضی اللہ عنہ فرماتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: "اے ان لوگوں کے گروہ جو صرف زبان سے ایمان لائے ہیں اور ایمان ابھی ان کے دلوں میں داخل نہیں ہوا! مسلمانوں کی غیبت مت کرو، اور ان کے چھپے ہوئے عیب مت ٹٹولو! کیونکہ جو شخص اپنے مسلمان بھائیوں کے عیب تلاش کرے گا اللہ اس کے عیبوں کا پیچھا کرے گا، اور اللہ جس کے عیبوں کا پیچھا کرے گا اسے اس کے اپنے گھر کے اندر رسوا اور ذلیل کر دے گا!" (مسند احمد: 4/420، صحیح)`,
