        arabicText: `عَنِ الشَّرِيدِ بْنِ سُوَيْدٍ الثَّقَفِيِّ رَضِيَ اللَّهُ عَنْهُ قَالَ: رَدِفْتُ رَسُولَ اللَّهِ ﷺ يَوْمًا فَقَالَ: «هَلْ مَعَكَ مِنْ شِعْرِ أُمَيَّةَ بْنِ أَبِي الصَّلْتِ شَيْءٌ؟» قُلْتُ: نَعَمْ، فَأَنْشَدْتُهُ بَيْتًا، فَقَالَ: «هِيهْ»، ثُمَّ أَنْشَدْتُهُ بَيْتًا، فَقَالَ: «هِيهْ»، حَتَّى أَنْشَدْتُهُ مِائَةَ بَيْتٍ. (مسند أحمد: 4/388، صحيح — رواه مسلم)`,
        urduTranslation: `حضرت شرید بن سوید ثقفی رضی اللہ عنہ فرماتے ہیں کہ ایک دن میں سواری پر رسول اللہ ﷺ کے پیچھے بیٹھا تو آپ نے فرمایا: "کیا تمہیں امیہ بن ابی الصلت کے توحید والے اشعار میں سے کچھ یاد ہے؟" میں نے عرض کیا: جی ہاں، پس میں نے آپ کو ایک شعر سنایا تو آپ نے فرمایا: "اور سناؤ"، پھر میں نے دوسرا شعر سنایا تو فرمایا: "اور سناؤ"، یہاں تک کہ میں نے آپ کو سو اشعار سنائے! (مسند احمد: 4/388، صحیح)`,
