        urduTranslation: `ام المؤمنین حضرت میمونہ رضی اللہ عنہا سے مروی ہے کہ انہوں نے ضرورت کے وقت قرض لیا، تو ان سے عرض کیا گیا: اے ام المؤمنین! آپ قرض لیتی ہیں جبکہ آپ کے پاس ادا کرنے کا کوئی مستقل ذریعہ نہیں؟ انہوں نے فرمایا: میں نے رسول اللہ ﷺ کو فرماتے سنا ہے: "جو شخص بھی کوئی قرض لیتا ہے اور اللہ تعالیٰ اس کی نیت میں یہ جانتا ہے کہ وہ اسے ضرور ادا کرنا چاہتا ہے، تو اللہ تعالیٰ دنیا ہی میں اس کی طرف سے وہ قرض خود ادا فرما دیتا ہے (اس کے اسباب بنا دیتا ہے)!" (مسند احمد: 6/330، صحیح)`,
