        arabicText: `عَنْ زَيْنَبَ بِنْتِ جَحْشٍ رَضِيَ اللَّهُ عَنْهَا، أَنَّ رَسُولَ اللَّهِ ﷺ دَخَلَ عَلَيْهَا يَوْمًا فَزِعًا يَقُولُ: «لَا إِلَهَ إِلَّا اللَّهُ، وَيْلٌ لِلْعَرَبِ مِنْ شَرٍّ قَدِ اقْتَرَبَ، فُتِحَ اليَوْمَ مِنْ رَدْمِ يَأْجُوجَ وَمَأْجُوجَ مِثْلُ هَذِهِ»، وَحَلَّقَ بِإِصْبَعَيْهِ الإِبْهَامِ وَالَّتِي تَلِيهَا، قَالَتْ زَيْنَبُ: فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَنَهْلِكُ وَفِينَا الصَّالِحُونَ؟ قَالَ: «نَعَمْ، إِذَا كَثُرَ الخَبَثُ». (مسند أحمد: 6/428، متفق علیه)`,
        urduTranslation: `ام المؤمنین حضرت زینب بنت جحش رضی اللہ عنہا فرماتی ہیں کہ ایک دن رسول اللہ ﷺ ان کے پاس گھبرائے ہوئے تشریف لائے اور فرما رہے تھے: "لا الہ الا اللہ! عربوں کے لیے اس شر اور فتنے کی وجہ سے بربادی ہے جو قریب آ چکا ہے! آج یاجوج و ماجوج کی دیوار میں سے اتنا سوراخ کھل گیا ہے"، اور آپ نے اپنے انگوٹھے اور ساتھ والی انگلی کا حلقہ بنا کر اشارہ فرمایا۔ حضرت زینب فرماتی ہیں کہ میں نے عرض کیا: یا رسول اللہ! کیا ہم ہلاک ہو جائیں گے حالانکہ ہمارے درمیان نیک لوگ بھی موجود ہوں گے؟ آپ ﷺ نے ارشاد فرمایا: "ہاں! جب خباثت اور گناہ کثرت سے پھیل جائیں گے!" (مسند احمد: 6/428، متفق علیہ)`,
