        urduTranslation: `ام المؤمنین حضرت صفیہ بنت حیی رضی اللہ عنہا فرماتی ہیں کہ نبی اکرم ﷺ اعتکاف میں تھے، میں رات کے وقت آپ کی زیارت کے لیے حاضر ہوئی۔ کچھ دیر گفتگو کے بعد جب میں واپس جانے کے لیے اٹھی تو آپ مجھے رخصت کرنے میرے ساتھ چلے۔ راستے میں دو انصاری صحابہ گزرے، جب انہوں نے نبی ﷺ کو دیکھا تو تیزی سے آگے بڑھنے لگے۔ آپ ﷺ نے فرمایا: "ٹھہرو! اطمینان سے چلو، یہ (میری زوجہ) صفیہ بنت حیی ہے!" انہوں نے عرض کیا: سبحان اللہ یا رسول اللہ! (کیا ہم آپ پر کوئی بدگمانی کر سکتے تھے؟) آپ ﷺ نے فرمایا: "بے شک شیطان انسان کے اندر خون کی طرح گردش کرتا ہے، اور مجھے ڈر ہوا کہ وہ کہیں تمہارے دلوں میں کوئی برا وسوسہ نہ ڈال دے!" (مسند احمد: 6/337، متفق علیہ)`,
        tashreeh: `یہ حدیث شریعت کا سنہری اصول سکھاتی ہے کہ انسان کو خود کو تہمت اور بدگمانی کی جگہوں سے بچانا چاہیے۔ اگر کسی جگہ غلط فہمی کا شبہ ہو تو فوراً وضاحت کر دینا عیب نہیں بلکہ سنتِ نبوی ہے تاکہ مسلمانوں کے دل بدگمانی اور شیطانی وسوسوں سے محفوظ رہیں۔`,
