        urduTranslation: `حضرت ام عطیہ انصاریہ رضی اللہ عنہا فرماتی ہیں کہ جب رسول اللہ ﷺ کی صاحبزادی (حضرت زینب رضی اللہ عنہا) کا وصال ہوا تو رسول اللہ ﷺ ہمارے پاس تشریف لائے اور فرمایا: "اسے تین، پانچ یا اس سے زیادہ بار اگر مناسب سمجھو پانی اور بیری کے پتوں سے غسل دو، اور آخری بار کے غسل میں کچھ کافور شامل کر لو، پھر جب تم فارغ ہو جاؤ تو مجھے اطلاع دینا!" (مسند احمد: 6/407، متفق علیہ)`,
