          { word: 'وَجَارُهُ جَائِعٌ', role: 'واو حالیة + مبتدأ مضاف + خبر المبتدأ مرفوع والجملة حالية', sign: 'ضمہ تنوین', detail: 'پڑوسی کا بھوکا ہونا' }
