        urduTranslation: `حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "علم دین کا حاصل کرنا ہر مسلمان پر فرض ہے، اور نااہل کے سامنے علم رکھنا ایسا ہے جیسے سوروں کے گلے میں موتی، ہیرے اور سونا لٹکانا۔" (مسند احمد: 3/288، حسن بشواہدہ)`,
        tashreeh: `دین کے بنیادی احکام، حلال و حرام کی پہچان اور عقائد کا علم ہر مسلمان مرد و عورت پر فرضِ عین ہے۔ علم نبوی کی عظمت کا تقاضا ہے کہ اس کی قدر کی جائے اور اسے صحیح و صالح قدردانوں تک پہنچایا جائے۔`,
