          { word: 'بَيْنَ الأَذَانِ وَالإِقَامَةِ', role: 'ظرف زمان منصوب مضاف + مضاف إليه مجرور + معطوف مجرور بالكسرة', sign: 'فتحہ وکسرہ', detail: 'مبارک وقفہ' }
