    titleUrdu: 'مسندِ حضرت انس بن مالک رضی اللہ عنہ (حدیث قدسی: اے ابنِ آدم! تو جب تک مجھ سے دعا کرتا رہے گا میں تجھے بخشتا رہوں گا)',
