        urduTranslation: `حضرت انس بن مالک رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "سحری کھایا کرو! کیونکہ سحری کھانے میں یقیناً بڑی برکت ہے۔" (مسند احمد: 3/99، متفق علیہ)`,
        tashreeh: `سحری کھانا سنتِ مؤکدہ ہے جو روزے دار کو دن بھر عبادات اور قوتِ عمل فراہم کرتی ہے۔ اس میں برکت دینی بھی ہے (سنت نبوی پر عمل، وقت سحر کی دعا و استغفار) اور دنیاوی بھی (جسمانی توانائی اور ضعف سے حفاظت)۔`,
