        urduTranslation: `حضرت انس بن مالک رضی اللہ عنہ روایت کرتے ہیں کہ رسول اللہ ﷺ نے فرمایا: "میری خصوصی شفاعت میری امت کے ان لوگوں کے لیے ہو گی جنہوں نے کبیرہ گناہ کیے ہوں گے۔" (مسند احمد: 3/213، صحیح)`,
