        arabicText: `عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ رَضِيَ اللَّهُ عَنْهُمَا، أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «رَحِمَ اللَّهُ رَجُلًا سَمْحًا إِذَا بَاعَ، وَإِذَا اشْتَرَى، وَإِذَا اقْتَضَى». (مسند أحمد: 3/356، حديث صحيح)`,
        urduTranslation: `حضرت جابر بن عبد اللہ رضی اللہ عنہما سے مروی ہے کہ رسول اللہ ﷺ نے دعا فرمائی: "اللہ تعالیٰ اس شخص پر رحمت نازل فرمائے جو بیچتے وقت، خریدتے وقت اور اپنے حق یا قرض کا تقاضا کرتے وقت نرمی اور کشادہ دلی کا مظاہرہ کرتا ہے۔" (مسند احمد: 3/356، صحیح)`,
