          { word: 'سَمْحًا إِذَا بَاعَ', role: 'نعت منصوبة بالفتحة + ظرف زمان خافض لشرطه متعلق بسَمحاً + جملة باع في محل جر بالإضافة', sign: 'فتحہ لفظاً', detail: 'نرم خو تاجر' }
