          { word: 'إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ', role: 'جار ومجرور ومضاف إليه + واو عاطفة + معطوف مجرور ومضاف إليه مجرور بالكسرة', sign: 'کسرہ لفظاً', detail: 'قلوب و اعمال کا مقام' }
