        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "اہلِ ایمان میں سب سے زیادہ کامل ایمان والا وہ شخص ہے جو سب سے بہترین اخلاق رکھتا ہو، اور تم میں سب سے بہتر وہ لوگ ہیں جو اپنی بیویوں اور گھر والوں کے لیے سب سے بہترین ہیں۔" (مسند احمد: 2/250، حسن صحیح)`,
