    titleUrdu: 'مسندِ حضرت ابو ہریرہ رضی اللہ عنہ (صدقہ مال کو کم نہیں کرتا، معاف کرنے سے اللہ عزت بڑھاتا ہے اور عاجزی والے کو بلندی دیتا ہے)',
