        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ ﷺ نے فرمایا: "جو شخص اللہ اور قیامت کے دن پر ایمان رکھتا ہے اسے چاہیے کہ وہ اچھی بات کہے ورنہ خاموش رہے، اور جو شخص اللہ اور آخرت کے دن پر ایمان رکھتا ہے اسے چاہیے کہ وہ اپنے پڑوسی کی عزت و اکرام کرے، اور جو شخص اللہ اور آخرت پر ایمان رکھتا ہے اسے چاہیے کہ وہ اپنے مہمان کی تکریم کرے۔" (مسند احمد: 2/267، متفق علیہ)`,
