        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے ارشاد فرمایا: "ایمان کی ستر سے کچھ زیادہ (یا ساٹھ سے کچھ زیادہ) شاخیں ہیں۔ ان میں سب سے افضل اور اعلیٰ شاخ 'لَا إِلَهَ إِلَّا اللَّهُ' کا اقرار ہے، اور اس کا سب سے ادنیٰ درجہ راستے سے تکلیف دہ چیز (پتھر، کانٹا) ہٹانا ہے، اور حیا بھی ایمان کا ایک اہم شعبہ اور شاخ ہے۔" (مسند احمد: 2/414، متفق علیہ)`,
