        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ ﷺ نے ارشاد فرمایا: "کامل مسلمان وہ ہے جس کی زبان اور ہاتھ (کی ایذا رسانی) سے دوسرے مسلمان محفوظ اور سلامت رہیں، اور کامل مؤمن وہ ہے جس سے لوگ اپنی جانوں اور اپنے مالوں کے بارے میں امن اور اطمینان میں رہیں۔" (مسند احمد: 2/379، حسن صحیح)`,
