        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ میں نے رسول اللہ ﷺ کو ارشاد فرماتے سنا: "جس شخص کو یہ بات پسند اور خوش کن ہو کہ اس کے رزق میں فراخی اور کشادگی کر دی جائے، اور اس کی عمر دراز کر کے اثر میں تاخیر کر دی جائے، تو اسے چاہیے کہ وہ اپنے رشتہ داروں کے ساتھ صلہ رحمی اور اچھا سلوک کرے۔" (مسند احمد: 2/247، متفق علیہ)`,
