          { word: 'يَوْمُ الْجُمُعَةِ', role: 'خبر المبتدأ مرفوع بالضمة مضاف + الجمعة مضاف إليه مجرور بالكسرة', sign: 'ضمہ وکسرہ', detail: 'جمعۃ المبارک' }
