        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ بیان کرتے ہیں کہ رسول اللہ ﷺ نے فرمایا: "رمضان کے (فرض روزوں کے) بعد سب سے افضل ترین روزے اللہ کے مہینے محرم الحرام کے ہیں، اور فرض نمازوں کے بعد سب سے افضل ترین نماز رات کی نماز (تہجد) ہے۔" (مسند احمد: 2/303، صحیح)`,
        tashreeh: `محرم الحرام کو 'شہر اللہ' (اللہ کا مہینہ) کہہ کر عزت بخشی گئی ہے کیونکہ یہ حرمت والے مہینوں میں سے ہے، خصوصاً عاشورہ (10 محرم) اور اس کے ساتھ 9 یا 11 محرم کا روزہ رکھنا سال بھر کے صغیرہ گناہوں کا کفارہ بنتا ہے۔ اسی طرح رات کی تنہائی میں پڑھی جانے والی نمازِ تہجد اخلاص کا اعلیٰ ترین نمونہ ہے۔`,
