          { word: 'شَهْرُ اللَّهِ الْمُحَرَّمُ', role: 'خبر المبتدأ مرفوع مضاف ولفظ الجلالة مضاف إليه + المحرم نعت لشهر مرفوع بالضمة', sign: 'ضمہ لفظاً', detail: 'ماہِ محرم' }
