          { word: 'لَيْسَ لَهُ جَزَاءٌ إِلَّا الْجَنَّةُ', role: 'ليس ناسخ + له شبه جملة خبر مقدم + جزاء اسمها مؤخر + إلا حصر + الجنة بدل أو خبر', sign: 'ضمہ لفظاً', detail: 'حج مبرور کی جزا' }
