        arabicText: `عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «لَوْلَا أَنْ أَشُقَّ عَلَى أُمَّتِي لَأَمَرْتُهُمْ بِالسِّوَاكِ عِنْدَ كُلِّ صَلَاةٍ»، وَفِي لَفْظٍ: «مَعَ كُلِّ وُضُوءٍ». (مسند أحمد: 2/245، متفق علیه)`,
        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے مروی ہے کہ رسول اللہ ﷺ نے فرمایا: "اگر مجھے اپنی امت پر مشقت اور تنگی میں پڑنے کا اندیشہ نہ ہوتا، تو میں انہیں ہر نماز کے وقت (اور ایک روایت میں: ہر وضو کے وقت) مسواک کرنے کا لازمی حکم فرماتا!" (مسند احمد: 2/245، متفق علیہ)`,
        tashreeh: `مسواک منہ کی صفائی اور رب تعالیٰ کی رضا مندی کا عظیم ذریعہ ہے۔ رسول اللہ ﷺ نے امت کی آسانی اور شفقت کے پیشِ نظر اسے فرض نہیں کیا تاکہ کوتاہی پر گناہگار نہ ہوں، لیکن اس کی بے انتہا ترغیب دی کہ ہر نماز اور وضو سے پہلے مسواک کرنا مؤکد سنت ہے۔`,
