          { word: 'فَذَلِكُمُ الرِّبَاطُ', role: 'فاء الفصيحة + اسم إشارة مبتدأ + الرباط خبر المبتدأ مرفوع بالضمة', sign: 'ضمہ لفظاً', detail: 'جہاد اور رباط کا درجہ' }
