          { word: 'مَا لَمْ يُحْدِثْ', role: 'ما مصدرية ظرفية + لم جازمة + يحدث مضارع مجزوم بالسكون والفاعل مستتر', sign: 'سکون لفظاً', detail: 'بے وضو ہونے کی قید' }
