          { word: 'عَنْ بَيْعِ الْغَرَرِ', role: 'جار ومجرور ومضاف إليه مجرور بالكسرة وهو ما طُوِيَ عنه علمه وجهلت عاقبته', sign: 'کسرہ لفظاً', detail: 'دھوکے کی بیع' }
