          { word: 'وَلَا تَنَاجَشُوا', role: 'واو عاطفة + لا ناهية + تناجشوا مضارع مجزوم بحذف النون والواو فاعل', sign: 'حذف النون', detail: 'جھوٹی بولی کی ممانعت' }
