          { word: 'رَضِيَ مِنْهَا آخَرَ', role: 'رضي ماض والفاعل مستتر جواب الشرط + جار ومجرور + آخَرَ مفعول به منصوب بالفتحة', sign: 'فتحہ لفظاً', detail: 'دوسری خوبی کی قدر' }
