        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی اکرم ﷺ نے فرمایا: "اللہ تعالیٰ نے ایسی کوئی بیماری نازل نہیں فرمائی جس کے لیے شفا اور دوا نازل نہ فرمائی ہو!" (مسند احمد: 2/358، متفق علیہ)`,
        tashreeh: `یہ حدیث میڈیکل ریسرچ اور علاج و معالجہ کروانے کی سب سے بڑی بنیاد اور امید افزا الہام ہے۔ ہر لاعلاج سمجھی جانے والی بیماری کی دوا اور علاج کائنات میں موجود ہے جسے ڈھونڈنا اہلِ طب کی ذمہ داری ہے، اور دوا کا استعمال توکل کے منافی نہیں بلکہ سنتِ نبوی ہے۔`,
