          { word: 'وَفِرَّ مِنَ الْمَجْذُومِ', role: 'واو عاطفة + فِرَّ فعل أمر مبني على السكون وحرك بالفتح للتضعيف + جار ومجرور متعلقان بفر', sign: 'فتحہ عارضی', detail: 'جذامی سے بچاؤ' }
