        id: 'musnad_ahmad_379_01',
        arabicText: `عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، قَالَ: قَالَ رَسُولُ اللَّهِ ﷺ: «إِنَّ اللَّهَ لَا يَنْظُرُ إِلَى صُوَرِكُمْ وَأَمْوَالِكُمْ، وَلَكِنْ يَنْظُرُ إِلَى قُلُوبِكُمْ وَأَعْمَالِكُمْ». (مسند أحمد: 2/285، حديث صحيح)`,
        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "بے شک اللہ تعالیٰ تمہاری ظاہری صورتوں اور تمہارے مال و دولت کو نہیں دیکھتا، بلکہ وہ تو تمہارے دلوں (کے اخلاص) اور تمہارے اعمال کو دیکھتا ہے!" (مسند احمد: 2/285، صحیح)`,
        tashreeh: `اللہ کے ہاں حسن، وجاہت، دولت اور حسب و نسب کی کوئی قیمت نہیں، بلکہ حقیقی معیار دل کی نیت اور پاکیزہ عمل ہے۔ جو شخص دل کے اخلاص کے ساتھ معمولی عمل بھی کرے وہ بارگاہِ الہی میں پہاڑ جتنا وزنی بن جاتا ہے، جبکہ دکھاوے کے پہاڑ جیسے اعمال خاک ہو جاتے ہیں۔`,
