    titleUrdu: 'مسندِ حضرت ابو ہریرہ رضی اللہ عنہ (پانچوں نمازیں اور ایک جمعہ سے دوسرا جمعہ درمیانی گناہوں کا کفارہ بن جاتے ہیں)',
