        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "پانچوں نمازیں، اور ایک جمعہ سے دوسرا جمعہ، اور ایک رمضان سے دوسرا رمضان، اپنے درمیانی گناہوں کا کفارہ بن جاتے ہیں، بشرطیکہ کبیرہ گناہوں سے بچا جائے!" (مسند احمد: 2/229، صحیح)`,
