        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: "تم تمام لوگوں کو اپنے مال و دولت سے مطمئن و خوش نہیں کر سکتے، لیکن تمہارا خندہ پیشانی سے ملنا اور تمہارا اچھا اخلاق ان سب کے دل جیت سکتا ہے!" (مسند احمد: 2/350، حسن)`,
