          { word: 'بَسْطُ', role: 'فاعل يَسَعُهُمْ مؤخر مرفوع وعلامة رفعه الضمة الظاهرة وهو مضاف', sign: 'ضمہ لفظاً', detail: 'کشادہ روئی' }
