        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "میانہ روی اختیار کرو اور درستی پر رہو، اور جان لو کہ تم میں سے کسی ایک کو بھی اس کا عمل تن تنہا نجات نہیں دلا سکتا!" (مسند احمد: 2/254، صحیح)`,
