        arabicText: `عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ، أَنَّ رَسُولَ اللَّهِ ﷺ قَالَ: «رَغِمَ أَنْفُ رَجُلٍ ذُكِرْتُ عِنْدَهُ فَلَمْ يُصَلِّ عَلَيَّ، وَرَغِمَ أَنْفُ رَجُلٍ دَخَلَ عَلَيْهِ رَمَضَانُ ثُمَّ انْسَلَخَ قَبْلَ أَنْ يُغْفَرَ لَهُ، وَرَغِمَ أَنْفُ رَجُلٍ أَدْرَكَ عِنْدَهُ أَبَوَيْهِ الْكِبَرَ فَلَمْ يُدْخِلَاهُ الْجَنَّةَ». (مسند أحمد: 2/254، حديث صحيح)`,
        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ رسول اللہ ﷺ نے فرمایا: "اس شخص کی ناک خاک آلود اور وہ ذلیل و خوار ہو جس کے سامنے میرا ذکر ہو اور وہ مجھ پر درود نہ بھیجے! اور اس شخص کی ناک خاک آلود ہو جس پر رمضان کا مہینہ آئے اور وہ اس کی بخشش ہوئے بغیر گزر جائے! اور اس شخص کی ناک خاک آلود ہو جس نے اپنے والدین میں سے دونوں کو یا ایک کو بڑھاپے میں پایا اور وہ دونوں اسے جنت میں داخل نہ کرا سکے (یعنی ان کی خدمت نہ کی)!" (مسند احمد: 2/254، صحیح)`,
