        tashreeh: `مصیبت کے وقت 'اگر یوں ہوتا تو یوں نہ ہوتا' کہنا اللہ کے فیصلے پر عدمِ رضا کی عکاسی کرتا ہے۔ شیطان اس موقع کو غنیمت جان کر وسوسے ڈالتا ہے، انسان کو ناشکرا بناتا ہے اور رب کی تقدیر پر اعتراضات کا شکار کر دیتا ہے۔`,
