        urduTranslation: `حضرت ابو ہریرہ رضی اللہ عنہ سے روایت ہے کہ نبی کریم ﷺ نے فرمایا: "اور وہ شخص جسے کسی اونچے منصب اور خوبصورتی والی عورت نے (گناہ کی طرف) بلایا، تو اس نے (صاف) جواب دیا: میں تو اللہ رب العزت سے ڈرتا ہوں!" (مسند احمد: 2/439، صحیح)`,
